# -*- coding: utf-8 -*-
Q = {
"21:1": "«اقترب للناس حسابهم» دربارهٔ نزدیکیِ زمانی حساب چه می‌گوید، در حالی که قرن‌ها از آن گذشته است؟ آیا «اقترب» به معنای نزدیکیِ تقویمی است، نزدیکی نسبت به عمر جهان، یا کنایه از حتمیت؟ و «معرضون» را چگونه باید با «غفلة» سنجید؟",
"21:2": "«ما یأتیهم من ذکر من ربهم محدث» دربارهٔ حدوثِ قرآن چه می‌گوید؟ آیا «محدث» به معنای تازه‌بودنِ نزول است یا خلقِ مخلوق، و این واژه چگونه به نزاع کلامی دربارهٔ قدیم یا حادث بودنِ کلام الهی راه یافته است؟",
"21:3": "چرا «لاهیة قلوبهم» پیش از «اسروا النجوی الذین ظلموا» می‌آید و «هل هذا الا بشر مثلکم» چه استدلالی دربارهٔ نبوت دارد؟ آیا اتهام «سحر» ادامهٔ همان انکارِ بشربودن است یا پاسخ به معجزه؟",
"21:4": "پاسخ پیامبر «ربی یعلم القول فی السماء والارض» به نجوا چه می‌گوید؟ چرا قرائت‌های «قل» و «قال» هر دو در این آیه آمده و آیا میان خطاب به پیامبر و گزارش پاسخ او تفاوتی در معنا است؟",
"21:5": "چهار اتهامِ پیاپی «اضغاث احلام»، «افتراه»، «شاعر» و «بل» چه نسبتی با هم دارند؟ آیا از سر سردرگمیِ منکران است یا ترتیبی منطقی، و «فلیأتنا بآیة کما ارسل الاولون» چه معیاری برای نبوت می‌خواهد؟",
"21:6": "«ما آمنت قبلهم من قریة اهلکناها افهم یؤمنون» چه استدلالی دربارهٔ معجزهٔ درخواستی دارد؟ آیا ایمان نیاوردنِ اقوام پیشین با وجود معجزه دلیل بر بی‌فایدگی نشانه‌ی حسی است؟",
"21:7": "«وما ارسلنا قبلک الا رجالاً نوحی الیهم» چرا بشربودن پیامبران را استدلالی بر نبوت می‌کند؟ و «اهل الذکر» چه کسانی‌اند: اهل کتاب، عالمان، یا اهل بیت؟ و این ارجاع به آنان چه معیاری برای اعتبار دارد؟",
"21:8": "«وما جعلناهم جسداً لا یاکلون الطعام» چه چیزی را نفی می‌کند و آیا «جسد» در اینجا فرشته‌گونه‌بودنِ پیامبران را رد می‌کند یا فقط بی‌نیازی از غذا را؟ و «وما کانوا خالدین» چه نسبتی با آن دارد؟",
"21:9": "«صدقناهم الوعد» وعدهٔ خدا به پیامبران را چگونه معنا می‌کند و «المسرفین» چه کسانی‌اند: کافران، یا هر که از حدود خدا درگذرد؟ آیا نجات «من نشاء» انتخابِ مشیت است یا با شایستگی گره خورده؟",
"21:10": "«لقد انزلنا الیکم کتاباً فیه ذکرکم» چه معنایی دارد: ذکر یعنی شرف، یاد، یا موعظه؟ و این‌که «افلا تعقلون» پرسشی انکاری است، دربارهٔ رابطهٔ عقل و پذیرش وحی چه می‌گوید؟",
"21:11": "«وکم قصمنا من قریة کانت ظالمة» چه معیاری برای هلاک می‌دهد: ظلم یا کفر؟ آیا «قصم» با «اهلکنا» تفاوتی دارد و «قوماً آخرین» چه می‌خواهد بگوید؟",
"21:12": "«فلما احسوا بأسنا اذا هم منها یرکضون» چه حسی را می‌گوید: حس ظاهری یا دریافتِ عقلی؟ و «یرکضون» گریز از شهر است یا گریز از عذاب؟",
"21:13": "«لا ترکضوا وارجعوا الی ما اترفتم فیه» خطاب فرشتگان است، خدا، یا پیامبر؟ و «لعلکم تسألون» پرسیده‌شدن از چه چیزی است: از نعمت‌ها، از اعمال، یا از اموال؟",
"21:14": "«قالوا یا ویلنا انا کنا ظالمین» اعترافی در لحظهٔ عذاب است؛ آیا چنین اقراری در این لحظه ارزشی دارد، یا نشانهٔ دیر شدن است؟ و چه فرقی با ایمانِ «اضطراری» دارد؟",
"21:15": "«فما زالت تلک دعواهم حتی جعلناهم حصیداً خامدین» حصید و خامد دو تصویر برای هلاک‌اند؛ چه نسبتی میان نالهٔ آنان و فروخفتنشان است و آیا «دعوی» ادعا است یا فریاد؟",
"21:16": "«وما خلقنا السماء والارض وما بینهما لاعبین» چه دلیلی بر معاد یا حکمت است؟ آیا نفی «لعب» ردِّ مذهبی خاص است یا اصلی کلی دربارهٔ هدفمندی آفرینش؟",
"21:17": "«لو اردنا ان نتخذ لهواً لاتخذناه من لدنا ان کنا فاعلین» «لهو» به چه معناست: همسر، فرزند، یا سرگرمی؟ و «ان کنا فاعلین» شرطی نفی‌کننده است یا اثبات‌کننده؟",
"21:18": "«بل نقذف بالحق علی الباطل فیدمغه» حق و باطل را چگونه در برابر هم می‌نشاند؟ «یدمغه» تصویر چیست و آیا این قاعده در تاریخ همیشه محقق است یا وعده‌ای آخرالزمانی؟",
"21:19": "«ومن عنده لا یستکبرون عن عبادته» فرشتگان را چگونه توصیف می‌کند و رابطهٔ «ومن عنده» با «له من فی السماوات والارض» چیست؟ آیا این آیه عبادتِ فرشتگان را الگو می‌کند یا علیه پرستش آن‌ها استدلال می‌کند؟",
"21:20": "«یسبحون اللیل والنهار لا یفترون» تسبیحِ مداوم را چگونه می‌فهمد: تسبیح لفظی یا ذاتی؟ و ادعای نفی «فتور» چه تفاوتی با ضعف انسان دارد؟",
"21:21": "«ام اتخذوا آلهة من الارض هم ینشرون» چرا خدایان را از «زمین» می‌داند و «ینشرون» چه ادعایی را به آنان نسبت می‌دهد: زنده‌کردن مردگان یا گسترش دعوت؟",
"21:22": "«لو کان فیهما آلهة الا الله لفسدتا» برهان تمانع چگونه از همین آیه برمی‌آید؟ آیا این یک برهان قطعی عقلی است یا اقناعی، و ضعف و قوت آن چه ربطی با «الا الله» دارد؟",
"21:23": "«لا یسأل عما یفعل وهم یسألون» پرسش‌ناپذیری فعلِ خدا چگونه با عدالتِ مسئولیت‌پذیر سازگار است؟ آیا این آیه دربارهٔ خلقت است، تقدیر، یا هر فعل الهی؟",
"21:24": "«قل هاتوا برهانکم» چه نقشی در روش قرآن دارد و «هذا ذکر من معی وذکر من قبلی» چه مرجعی را برای اثبات توحید می‌شمارد؟ آیا یک سنت مشترکِ پیامبران مستقل از استدلال عقلی است؟",
"21:25": "«وما ارسلنا من قبلک من رسول الا نوحی الیه انه لا اله الا انا فاعبدون» توحید را اصل مشترک همهٔ رسالت‌ها می‌گوید؛ آیا این ادعا با اختلاف شرایع و احکام سازگار است؟",
"21:26": "«وقالوا اتخذ الرحمن ولداً» به چه گروهی اشاره دارد: مشرکان دربارهٔ فرشتگان، یا اهل کتاب دربارهٔ مسیح و عزیر؟ و «بل عباد مکرمون» دربارهٔ جایگاه فرشتگان چه می‌گوید؟",
"21:27": "«لا یسبقونه بالقول وهم بامره یعملون» عصمت فرشتگان را از کدام ادبی می‌گیرد: ادب در سخن یا اطاعت در عمل؟ و آیا آیه ایشان را در برابر اراده الهی مجبور می‌داند؟",
"21:28": "«یعلم ما بین ایدیهم وما خلفهم ولا یشفعون الا لمن ارتضی» شفاعتِ فرشتگان را چگونه محدود می‌کند؟ «ارتضی» چه کسی را می‌گیرد و این آیه با شفاعتِ پیامبران و امامان چه نسبتی دارد؟",
"21:29": "«ومن یقل منهم انی اله من دونه فذلک نجزیه جهنم» چرا فرضِ ادعای الوهیتِ فرشته را مطرح می‌کند؟ آیا این فرضی تعلیمی است یا واقعی؟ و چه تفاوتی میان این فرض و عصمت فرشتگان است؟",
"21:30": "«ان السماوات والارض کانتا رتقاً ففتقناهما» به پیوستگی و گشایش چه می‌گوید: ابتدای آفرینش، بارش و رویش، یا پدیده‌ای دیگر؟ و تطبیق این آیه با نظریه‌های کیهان‌شناسی جدید چه شرایط و محدودیت‌هایی دارد؟",
"21:31": "«والقینا فی الارض رواسی ان تمید بهم» کارکرد کوه‌ها را در پایداری زمین می‌گوید؛ این بیان توصیفی تجربی است یا استعاری؟ و «فجاجاً سبلاً» به چه کارکردی اشاره دارد؟",
"21:32": "«وجعلنا السماء سقفاً محفوظاً» به چه چیزی اشاره دارد: جو، آسمانِ مادی، یا حفظ از شیاطین؟ و «وهم عن آیاتها معرضون» نسبت میان نشانه‌های طبیعی و اعراض را چگونه می‌بیند؟",
"21:33": "«کل فی فلک یسبحون» از «فلک» چه تصویری می‌دهد: مدار، کره، یا مسیر؟ و آیا ضمیر جمع ذوی‌العقل «یسبحون» برای اجرام آسمانی استفاده‌ای ادبی است یا دلالت دیگری دارد؟",
"21:34": "«وما جعلنا لبشر من قبلک الخلد افان مت فهم الخالدون» پاسخی به شماتتِ مرگ پیامبر است؛ این اعلام چه رابطه‌ای با طرح «خلود» در برابر آموزهٔ ثبات نبوت دارد؟",
"21:35": "«کل نفس ذائقة الموت ونبلوکم بالشر والخیر فتنة» چرا «شر» پیش از «خیر» می‌آید و آیا «فتنة» آزمونی بر ایمان است یا بر شکر و صبر؟ و ارتباط مرگ با آزمون چیست؟",
"21:36": "«وإذا رآک الذین کفروا ان یتخذونک الا هزواً» استهزای قوم چه جایگاهی در داستان پیامبران دارد؟ و «هم بذکر الرحمن هم کافرون» دو گروه یا یک گروه را می‌شناساند؟",
"21:37": "«خلق الانسان من عجل» آیا «عجل» به معنای شتاب‌زدگیِ ذاتی انسان است یا استعاره برای خمیرمایهٔ آفرینش؟ و «فلا تستعجلون» با نمونه‌های استعجال عذاب چه نسبتی دارد؟",
"21:38": "«متی هذا الوعد ان کنتم صادقین» پرسشِ استهزاآمیز است؛ چرا قرآن زمان وقوع قیامت را پاسخ نمی‌دهد و پاسخ آن را در آیات بعد به «لو یعلم الذین کفروا» می‌سپارد؟",
"21:39": "«حین لا یکفون عن وجوههم النار ولا عن ظهورهم» عذاب را از چهره و پشت می‌داند؛ این تصویر حسی است یا تمثیلی، و «ولا هم ینصرون» چه جایگاهی در رد پناه‌جویی دارد؟",
"21:40": "«بل تأتیهم بغتة فتبهتهم» چرا عذاب «بغتة» و «تبهتهم» وصف می‌شود و این غافل‌گیری چه نسبتی با درخواست «متی هذا الوعد» دارد؟",
}
